// Preferences DataStore — untyped file, typed keys
val Context.settings by preferencesDataStore("settings")
val THEME = stringPreferencesKey("theme")

val theme: Flow<String> = context.settings.data
  .catch { e -> if (e is IOException) emit(emptyPreferences()) else throw e }
  .map { it[THEME] ?: "system" }

suspend fun setTheme(v: String) { context.settings.edit { it[THEME] = v } }

// Proto DataStore with kotlinx.serialization — a schema without protoc
@Serializable
data class UserSettings(val theme: String = "system", val notifications: Boolean = true)

object UserSettingsSerializer : Serializer<UserSettings> {
  override val defaultValue = UserSettings()
  override suspend fun readFrom(input: InputStream): UserSettings =
    try { Json.decodeFromString(input.readBytes().decodeToString()) }
    catch (e: SerializationException) { throw CorruptionException("bad settings", e) }
  override suspend fun writeTo(t: UserSettings, output: OutputStream) {
    output.write(Json.encodeToString(t).encodeToByteArray())
  }
}

val Context.user by dataStore("user_settings.json", UserSettingsSerializer)

val notifications: Flow<Boolean> = context.user.data.map { it.notifications }

suspend fun setUserTheme(v: String) {
  context.user.updateData { it.copy(theme = v) }      // read-modify-write, atomic
}

