// 1) UI reads from Room — the Flow always carries the latest local state
class TodoRepo(private val dao: TodoDao, private val api: TodoApi) {
  fun observe(): Flow<List<Todo>> = dao.observeAll().map { rows -> rows.map { it.toDomain() } }

  suspend fun add(title: String) {
    val local = TodoEntity(
      id = UUID.randomUUID().toString(),     // client id: survives the round trip
      title = title,
      done = false,
      dirty = true,                          // pending — not yet on the server
      updatedAt = System.currentTimeMillis()
    )
    dao.upsert(local)                        // optimistic write, UI updates now
    OutboxScheduler.scheduleSync(context)
  }
}

// 2) Background sync — push local changes, then pull
class SyncWorker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {
  override suspend fun doWork(): Result {
    for (t in dao.getDirty()) {
      try {
        api.upsert(t.toDto())
        dao.markClean(t.id)
      } catch (e: IOException) {
        return Result.retry()                // transient: WorkManager backs off
      } catch (e: HttpException) {
        if (e.code() in 400..499) dao.markConflicted(t.id) else return Result.retry()
      }
    }
    val server = api.fetchAll()
    dao.mergeRemote(server.map { it.toEntity() })   // keep rows still dirty locally
    return Result.success()
  }
}

// 3) One queue, not one worker per edit
object OutboxScheduler {
  fun scheduleSync(ctx: Context) {
    val request = OneTimeWorkRequestBuilder<SyncWorker>()
      .setConstraints(
        Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()
      )
      .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
      .build()
    WorkManager.getInstance(ctx).enqueueUniqueWork(
      "sync_todos",
      ExistingWorkPolicy.APPEND_OR_REPLACE,   // APPEND blocks forever after a failure
      request
    )
  }
}

// A hardware-backed AES key that never leaves the Keystore
fun ensureKey(alias: String) {
  val ks = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
  if (ks.containsAlias(alias)) return
  KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore").apply {
    init(
      KeyGenParameterSpec.Builder(
        alias,
        KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
      )
        .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
        .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
        .setKeySize(256)
        .build()
    )
    generateKey()
  }
}

private fun secretKey(alias: String): SecretKey =
  (KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
    .getEntry(alias, null) as KeyStore.SecretKeyEntry).secretKey

fun encrypt(alias: String, plain: ByteArray): ByteArray {
  val cipher = Cipher.getInstance("AES/GCM/NoPadding")
  cipher.init(Cipher.ENCRYPT_MODE, secretKey(alias))
  return cipher.iv + cipher.doFinal(plain)      // keep the 12-byte IV with the payload
}

fun decrypt(alias: String, blob: ByteArray): ByteArray {
  val cipher = Cipher.getInstance("AES/GCM/NoPadding")
  cipher.init(Cipher.DECRYPT_MODE, secretKey(alias), GCMParameterSpec(128, blob, 0, 12))
  return cipher.doFinal(blob, 12, blob.size - 12)
}

// Store the ciphertext anywhere — DataStore, a file, a Room column
suspend fun saveToken(token: String) {
  ensureKey("auth")
  val blob = Base64.encodeToString(encrypt("auth", token.toByteArray()), Base64.NO_WRAP)
  context.dataStore.edit { it[TOKEN] = blob }
}

